#include "stdafx.h"#include "Queue.h"#include "..\Lang.h"////~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структура работы с задвижкойtypedef struct : public Queue_PRS  {  CShPolyHS sh;  int nType;  int nValue;  bool mBool;  bool mLamp;  int nHS;  bool bView;  bool m_bStopControlSP;  int nKlapanStop;  } Queue_PolyST;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияvoid ChangePolyLamp(Queue_PolyST* p, SQueue& q, CShPolyHS& sh){	if (sh.PV==2)		p->mBool=(q.m_dwMainTimer%2==0);	else		p->mBool=(sh.PV!=0);}int PaintPolyST(DefinePaint)  {  QueueP(Queue_PolyST);  //  if ( p->nHS >= 0 )  {      CShHS& Sh = (CShHS&)q.m_pPipe->SH(p->nHS);      if ( Sh.RetCode == CShBase::rcOK )	  {			p->bView = Sh.mOn;	  }  }  if ( p->nKlapanStop>=0)  {		CShKlapan& Sh = (CShKlapan&)q.m_pPipe->SH(p->nKlapanStop);		if (Sh.VentZ<100)			p->m_bStopControlSP=true;		else			p->m_bStopControlSP=false;  }  CShPolyHS& sh = (CShPolyHS&)PipeSH;  if ( IsTypeOK )    {		if ( !p->m_bPressed )			memcpy( &p->sh, &sh, sizeof( p->sh ) );		if (p->mLamp)			ChangePolyLamp(p,q,sh);    }  else  if ( ::GetMnemoStyle() & MNEMO_EDIT )    {    RECT rc = p->mRect;    ::InflateRect( &rc, 2, 2 );    CMyBrush brush( hDC, 0x0080ff );    brush.Rect( rc );    }  //  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция посылки сообщенияstatic void fnSendData(void* base,void* pVoid,bool bMessage)  {  ASS( base )  Queue_PolyST* p = (Queue_PolyST*)base;  if ( !ISTypeOK ) return;  //  if ( p->nType == 1 )    {    int nOld = p->sh.SP;    int nNew = p->nValue;    p->send.Set( &nOld, &nNew );    }  else  {    p->send.SetNew( pVoid );	if (Version==UPO_KF)	{		if ((p->send.nOld==0)&&(p->send.nNew==0))			p->send.nOld=1;		else		if ((p->send.nOld==2)&&(p->send.nNew==0))			p->send.nOld=1;		else		if ((p->send.nOld==0)&&(p->send.nNew==2))		{			p->send.nNew=1;			p->pPipe->SendData( p->send, bMessage );			p->send.nNew=2;		}		else		if ((p->send.nOld==1)&&(p->send.nNew==2))		{			p->send.nOld=0;			p->send.nNew=1;			p->pPipe->SendData( p->send, bMessage );			p->send.nOld=1;			p->send.nNew=2;		}	}  }  if (Version==NGU_MNPZ)  {			if ((p->send.nOld==0)&&(p->send.nNew==0))				p->send.nOld=1;			if ((p->send.nOld==1)&&(p->send.nNew==1))				p->send.nOld=0;  }  p->pPipe->SendData( p->send, bMessage );  p->m_bPressed = !bMessage;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void FillPoly( SPriborBase* d, void* pp )  {  d->fnData = fnSendData;  Queue_PolyST* p = (Queue_PolyST*)pp;  if ( p->nType == 1 )  {    d->pVoid = &p->mBool;  }  if ( p->mLamp )  {    d->pVoid = &p->mBool;	if ( p->nHS >= 0)    {		SPriborBool* a = (SPriborBool*)d;		a->pbOther = &p->bView;    }  }  if ( d->pVoid == &p->sh.SP&& lstrcmp( p->send.szValue, "SP_WITH_STOP" ) == 0 )       d->pbBlock = &p->m_bStopControlSP;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddPolyST(DefineTegs)  {  //  AddQueueEx(Queue_PolyST);  //  CShPolyHS sh;  memcpy( &p->sh, &sh, sizeof(p->sh) );  p->pSH = &p->sh;  //  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintPolyST;  p->mLamp=false;  p->nHS    = -1;  char szHS[64] = "";  char szSF[64] = "";  p->m_bStopControlSP=false;  char szKlapanStop[64] = "";  p->nKlapanStop=-1;  //  STegObj obj[] =    {    { 'I', "type" , &p->nType  },    { 'I', "value", &p->nValue },	{ 'B', "lamp", &p->mLamp },	{ 'S', "view", szHS, 63 },	{ 'S', "stop", szKlapanStop, 63 },	{ 'S', "suff", szSF, 63 },    // Дополнительная информация    EXT_QUEUE    };::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  //  int nActive = def.GetActiveObj();  if ( *szHS )    p->nHS = def.AddKind(id_HS,szHS);  if ( *szKlapanStop )	  p->nKlapanStop=def.AddKind(id_Klapan,szKlapanStop);  if ( *szSF )    {		const char* name = def.GetModelName(nActive);		char szName[128];		sprintf_s( szName, sizeof(szName), "%s%s", name, szSF );		def.AddKindPipe(id_PHS,szName);		def.m_queue.m_pPipe->End();		def.m_queue.m_pSocket->Refresh();    }  AddPriborsPipe( def, teg, Buffer, p, &FillPoly, id_PHS );  if ( *szSF )      def.m_queue.m_pPipe->m_nActive = nActive;  //  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~